-- Equipment becomes a dimension of the workout, not the exercise identity.
-- Generated by /tmp/gen-0015.mjs from src/db/seed (deriveBases). See
-- docs/design-equipment-as-dimension.md. Additive + reversible: old equipment-
-- named rows are archived, never dropped, so a repoint can be undone.

-- 0. Drop the vestigial `movement` column from 0014. The grouping model it
--    supported was replaced by base exercises (each exercise IS a movement now),
--    and its NOT-NULL + length check would reject base inserts and custom-exercise
--    sync, which never set it.
drop index if exists exercises_movement;
alter table exercises drop constraint if exists exercises_movement_not_empty;
alter table exercises drop column if exists movement;

-- 1. exercises: base-model columns; retire the per-row scalar equipment.
alter table exercises add column equipment_options equipment[] not null default '{}';
alter table exercises add column unilateral_equipment equipment[] not null default '{}';
alter table exercises alter column equipment drop not null;
alter table exercises alter column is_unilateral drop not null;

