-- 3. Custom rows (user-authored) keep their id; options come from their old scalar.
update exercises set
  equipment_options = array[equipment],
  unilateral_equipment = case when is_unilateral then array[equipment] else '{}'::equipment[] end
where user_id is not null and equipment_options = '{}' and equipment is not null;

-- 4. Equipment on the workout/template rows.
alter table workout_exercises add column equipment equipment;
alter table template_exercises add column equipment equipment;

