update template_exercises te set equipment = m.equipment::equipment, exercise_id = m.base_id
  from m where te.exercise_id = m.old_id;

-- 6. Custom rows not in the mapping: equipment from the base row itself.
update workout_exercises we set equipment = e.equipment_options[1]
  from exercises e where e.id = we.exercise_id and we.equipment is null;
update template_exercises te set equipment = e.equipment_options[1]
  from exercises e where e.id = te.exercise_id and te.equipment is null;

-- Any still-null row references an unknown exercise; default so NOT NULL holds.
update workout_exercises set equipment = 'other' where equipment is null;
update template_exercises set equipment = 'other' where equipment is null;
alter table workout_exercises alter column equipment set not null;
alter table template_exercises alter column equipment set not null;

